package org.asyncttwiz.fixtures

import org.asyncttwiz.protocol.*

/** Accepted realistic history, generated by the production incremental reducer (never bulk forged).
 * Shared by KMP protocol tests and JVM/Android adapter acceptance tests. */
object ScaleGames {
    fun id(n: Int) = "00000000-0000-4000-8000-${n.toString().padStart(12, '0')}"
    val a = id(7)
    val b = id(8)
    val card = id(9)
    val pingTarget = PingTarget(PingTargetKind.CARD, card)
    fun command(tree: GameplayTree, action: GameAction, n: Int) = GameCommand(id(n),
        GameScope(tree.initial.gameId, playId = tree.initial.id), action, id(90), "1")

    fun play(tree: GameplayTree, action: PlayAction, n: Int, actor: String = a): GameplayTree =
        change(tree, command(tree, GameAction.Play(action), n), actor)

    fun change(tree: GameplayTree, command: GameCommand, actor: String = a): GameplayTree {
        val change = HistoryContinuation.change(tree, actor, command)
        return checkNotNull(change.tree) { "Scale fixture ${command.action}: ${change.reason ?: change.outcome}" }
    }

    fun root(): PlayState {
        val definition = CardDefinition("Scale Wizard", listOf(DefinitionFace(id(11), "Wizard", corner = "2/2")))
        val digest = DeckJson.digest(definition)
        val cards = listOf(PlayCard(card, digest, a, id(10), id(11),
            placement = PlayPlacement(BoardPosition(0, 0), id(30))),
            PlayCard(id(12), digest, b, id(10), id(11), placement = PlayPlacement(BoardPosition(1024, 0), id(31))))
        return PlayState(id(1), id(2), id(3), id(4), PlayRoot(id(5), id(6)), id(5),
            BoardState(listOf(PlayPlayer(a), PlayPlayer(b)), cards, listOf(
                PlayContainer(id(10), PlayZone.BATTLEFIELD, cards = cards.map { it.id }),
                PlayContainer(id(13), PlayZone.GRAVEYARD), PlayContainer(id(14), PlayZone.STACK)), TurnState(a)),
            listOf(SubmittedDefinition(digest, definition)), emptyList(), InitialStarter(StarterChoice(a), a))
    }

    fun build(actions: Int, initial: PlayState = root()): GameplayTree {
        var tree = GameplayTree(initial)
        repeat(actions) { n ->
            val state = checkNotNull(tree.preparedState(tree.currentNodeId))
            val board = state.board
            val action = when (n % 24) {
                0, 1 -> PlayAction.SetTapped(card, !board.cards.first().tapped)
                2 -> PlayAction.AdjustLife(a, "1")
                3 -> PlayAction.AdjustPlayerCounter(a, CounterColor.entries.first(), "1")
                4 -> PlayAction.MoveCard(id(12), MoveSource(id(10), board.cards[1].placement), MoveDestination(id(13), MoveInsertion.UNORDERED))
                5 -> PlayAction.MoveCard(id(12), MoveSource(id(13)), MoveDestination(id(10), MoveInsertion.EMPTY, BoardPosition(1024, 0)))
                6 -> PlayAction.Stack(StackAction.AddEffect(card, GameplayRules.stackDigest(state)))
                7 -> PlayAction.Stack(StackAction.RemoveEffect(board.stackEffects.single().id))
                8 -> PlayAction.Combat(CombatAction.Open)
                9 -> PlayAction.Combat(CombatAction.Declare(checkNotNull(board.combat).id, card))
                10 -> PlayAction.Combat(CombatAction.Remove(checkNotNull(board.combat).id, board.combat!!.pairs.single().attackers.single().id))
                11 -> PlayAction.Combat(CombatAction.Close(checkNotNull(board.combat).id))
                12 -> PlayAction.Ping(EventReference(state.id, state.currentNodeId), pingTarget)
                13 -> PlayAction.Unping(tree.nodes.getValue(tree.currentNodeId).transition.annotation!!.reference.reference, pingTarget)
                14 -> PlayAction.EventComment(EventReference(state.id, state.currentNodeId), "Review this play $n")
                15 -> PlayAction.AdjustLife(b, "-1")
                else -> PlayAction.SetTapped(card, !board.cards.first().tapped)
            }
            val actor = if (n % 24 == 15) b else a
            var command = command(tree, GameAction.Play(action), 1000 + n)
            // A few real offshoots, only one edge from an already materialized endpoint.
            if (n > 0 && n % 2400 == 0) command = command.copy(action = GameAction.Play(PlayAction.AdjustLife(a, "1")),
                continuation = Continuation(tree.nodes.getValue(tree.currentNodeId).parentId, true))
            tree = change(tree, command, actor)
            if (n % 240 == 23) {
                tree = change(tree, command(tree, GameAction.Undo, 100000 + n))
                tree = change(tree, command(tree, GameAction.Redo, 200000 + n))
            }
        }
        return tree
    }
}
